import{_ as p,a0 as l,w as o,s as r,ao as d,I as i,x as s,a1 as n,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const $=JSON.parse('{"title":"awk 系列：如何使用 awk 比較操作符 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何使用 awk 比較操作符 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何使用 awk 比較操作符 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何使用 awk 比較操作符 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 4 - How to Use Comparison Operators with Awk in Linux","title":"awk 系列：如何使用 awk 比較操作符","tag":"awk","desc":""},"relativePath":"awk/Part 4 - How to Use Comparison Operators with Awk in Linux.md","filePath":"[post].md"}'),k={name:"awk/Part 4 - How to Use Comparison Operators with Awk in Linux.md"};function c(w,a,u,h,g,m){const t=l("Link");return o(),r("div",null,[a[13]||(a[13]=d(`<h1 id="awk-系列-如何使用-awk-比較操作符" tabindex="-1">awk 系列：如何使用 awk 比較操作符 <a class="header-anchor" href="#awk-系列-如何使用-awk-比較操作符" aria-label="Permalink to “awk 系列：如何使用 awk 比較操作符”">​</a></h1><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/Use-Comparison-Operators-with-AWK.png" alt=""></p><p>對於 使用 awk 命令的用户來説，處理一行文本中的數字或者字符串時，使用比較運算符來過濾文本和字符串是十分方便的。</p><p>在 awk 系列的此部分中，我們將探討一下如何使用比較運算符來過濾文本或者字符串。如果你是程序員，那麼你應該已經熟悉了比較運算符；對於其它人，下面的部分將介紹比較運算符。</p><h3 id="awk-中的比較運算符是什麼" tabindex="-1">awk 中的比較運算符是什麼？ <a class="header-anchor" href="#awk-中的比較運算符是什麼" aria-label="Permalink to “awk 中的比較運算符是什麼？”">​</a></h3><p>awk 中的比較運算符用於比較字符串和或者數值，包括以下類型：</p><ul><li><code>&gt;</code> – 大於</li><li><code>&lt;</code> – 小於</li><li><code>&gt;=</code> – 大於等於</li><li><code>&lt;=</code> – 小於等於</li><li><code>==</code> – 等於</li><li><code>!=</code> – 不等於</li><li><code>some_value ~ / pattern/</code> – 如果 some_value 匹配模式 pattern，則返回 true</li><li><code>some_value !~ / pattern/</code> – 如果 some_value 不匹配模式 pattern，則返回 true</li></ul><p>現在我們通過例子來熟悉 awk 中各種不同的比較運算符。</p><p>在這個例子中，我們有一個文件名為 food_list.txt 的文件，裏面包括不同食物的購買列表。我想給食物數量小於或等於 30 的物品所在行的後面加上<code>(**)</code></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>File – food_list.txt</span></span>
<span class="line"><span>No      Item_Name               Quantity        Price</span></span>
<span class="line"><span>1       Mangoes                    45           $3.45</span></span>
<span class="line"><span>2       Apples                     25           $2.45</span></span>
<span class="line"><span>3       Pineapples                 5            $4.45</span></span>
<span class="line"><span>4       Tomatoes                   25           $3.45</span></span>
<span class="line"><span>5       Onions                     15           $1.45</span></span>
<span class="line"><span>6       Bananas                    30           $3.45</span></span></code></pre></div><p>Awk 中使用比較運算符的通用語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 表達式 { 動作; }</span></span></code></pre></div><p>為了實現剛才的目的，執行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;$3 &lt;= 30 { printf &quot;%s\\t%s\\n&quot;, $0,&quot;**&quot; ; } $3 &gt; 30 { print $0 ;}&#39; food_list.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No	Item_Name\`		Quantity	Price</span></span>
<span class="line"><span>1	Mangoes	      		   45		$3.45</span></span>
<span class="line"><span>2	Apples			   25		$2.45	**</span></span>
<span class="line"><span>3	Pineapples		   5		$4.45	**</span></span>
<span class="line"><span>4	Tomatoes		   25		$3.45	**</span></span>
<span class="line"><span>5	Onions			   15           $1.45	**</span></span>
<span class="line"><span>6	Bananas			   30           $3.45	**</span></span></code></pre></div><p>在剛才的例子中，發生如下兩件重要的事情：</p><ul><li>第一個“表達式 {動作;}”組合中， <code>$3 &lt;= 30 { printf “%s\\t%s\\n”, $0,”**” ; }</code> 打印出數量小於等於30的行，並且在後面增加<code>(**)</code>。物品的數量是通過 <code>$3</code> 這個域變量獲得的。</li><li>第二個“表達式 {動作;}”組合中， <code>$3 &gt; 30 { print $0 ;}</code> 原樣輸出數量小於等於 <code>30</code> 的行。</li></ul><p>再舉一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;$3 &lt;= 20 { printf &quot;%s\\t%s\\n&quot;, $0,&quot;TRUE&quot; ; } $3 &gt; 20  { print $0 ;} &#39; food_list.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>No	  Item_Name		Quantity	Price</span></span>
<span class="line"><span>1	    Mangoes			   45		  $3.45</span></span>
<span class="line"><span>2	    Apples			   25		  $2.45</span></span>
<span class="line"><span>3	    Pineapples		  5		  $4.45	TRUE</span></span>
<span class="line"><span>4	    Tomatoes		   25		  $3.45</span></span>
<span class="line"><span>5	    Onions			   15     $1.45	TRUE</span></span>
<span class="line"><span>6     Bananas	       30     $3.45</span></span></code></pre></div><p>在這個例子中，我們想通過在行的末尾增加 (TRUE) 來標記數量小於等於20的行。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>這是一篇對 awk 中的比較運算符介紹性的指引，因此你需要嘗試其他選項，發現更多使用方法。</p><p>如果你遇到或者想到任何問題，請在下面評論區留下評論。請記得閲讀 awk 系列下一部分的文章，那裏我將介紹組合表達式。</p><hr>`,23)),i("p",null,[a[1]||(a[1]=s("via: ",-1)),n(t,{href:"http://www.tecmint.com/comparison-operators-in-awk/"},{default:e(()=>[...a[0]||(a[0]=[s("http://www.tecmint.com/comparison-operators-in-awk/",-1)])]),_:1})]),i("p",null,[a[5]||(a[5]=s("作者：",-1)),n(t,{href:"http://www.tecmint.com/author/aaronkili/"},{default:e(()=>[...a[2]||(a[2]=[s("Aaron Kili",-1)])]),_:1}),a[6]||(a[6]=s(" 譯者：",-1)),n(t,{href:"https://github.com/chunyang-wen"},{default:e(()=>[...a[3]||(a[3]=[s("chunyang-wen",-1)])]),_:1}),a[7]||(a[7]=s(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:e(()=>[...a[4]||(a[4]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[10]||(a[10]=s("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[8]||(a[8]=[s("LCTT",-1)])]),_:1}),a[11]||(a[11]=s(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:e(()=>[...a[9]||(a[9]=[s("Linux中國",-1)])]),_:1}),a[12]||(a[12]=s(" 榮譽推出",-1))])])}const T=p(k,[["render",c]]);export{$ as __pageData,T as default};
